question.solution:
class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def build_tree(preorder, inorder):
    if not preorder and not inorder:
        return None
    if len(preorder) != len(inorder):
        return None
    if sorted(preorder) != sorted(inorder):
        return None

    def build(pl, pr, il, ir):
        if pl > pr:
            return None
        node = TreeNode(preorder[pl])
        k = inorder.index(preorder[pl], il, ir + 1)
        left_size = k - il
        node.left = build(pl + 1, pl + left_size, il, k - 1)
        node.right = build(pl + left_size + 1, pr, k + 1, ir)
        return node

    return build(0, len(preorder) - 1, 0, len(inorder) - 1)

def pre_of(root):
    if root is None:
        return []
    return [root.val] + pre_of(root.left) + pre_of(root.right)

def in_of(root):
    if root is None:
        return []
    return in_of(root.left) + [root.val] + in_of(root.right)

root = build_tree([3, 9, 20, 15, 7], [9, 3, 15, 20, 7])
print(pre_of(root), in_of(root))
print(build_tree([], []))
one = build_tree([1], [1])
print(pre_of(one), in_of(one))
skew = build_tree([3, 2, 1], [1, 2, 3])
print(pre_of(skew), in_of(skew))

